// server/sec/crypto.ts
import { createCipheriv, createDecipheriv, createHash, createHmac, randomBytes as randomBytes2, timingSafeEqual } from "node:crypto";
function privacyHash(value) {
  const salt = process.env.APP_ENCRYPTION_KEY ?? "tradeport";
  return createHmac("sha256", salt).update(value).digest("hex").slice(0, 32);
}

// server/sec/risk.ts
async function recordEvent(e) {
  await exec("INSERT INTO security_events (at, address, kind, severity, details, ip_hash) VALUES ($1, $2, $3, $4, $5, $6)", [Date.now(), e.address ?? null, e.kind, e.severity ?? "info", JSON.stringify(e.details ?? {}).slice(0, 2000), e.ipHash ?? null]);
}

// server/auth.ts
var SESSION_TTL_MS = 7 * 24 * 60 * 60 * 1000;
function clientMeta(c, deviceId) {
  const ip = (c.req.header("x-forwarded-for") ?? "local").split(",").pop().trim();
  const ua = (c.req.header("user-agent") ?? "").slice(0, 200);
  const dev = typeof deviceId === "string" && /^[A-Za-z0-9_-]{8,80}$/.test(deviceId) ? deviceId : null;
  return { userAgent: ua, ipHash: privacyHash(ip), deviceHash: dev ? privacyHash(`dev:${dev}`) : null };
}
function hashToken(token) {
  return createHash2("sha256").update(token).digest("hex");
}
async function createSession(address, meta) {
  const token = randomBytes3(32).toString("hex");
  const now = Date.now();
  await exec(`INSERT INTO sessions (token, address, expires_at, created_at, last_seen, device_hash, user_agent, ip_hash)
     VALUES ($1, $2, $3, $4, $4, $5, $6, $7)`, [hashToken(token), address, now + SESSION_TTL_MS, now, meta.deviceHash, meta.userAgent, meta.ipHash]);
  let newDevice = false;
  if (meta.deviceHash) {
    const known = await one("SELECT 1 AS x FROM user_devices WHERE address = $1 AND device_hash = $2", [address, meta.deviceHash]);
    if (!known) {
      newDevice = true;
      const others = await one("SELECT 1 AS x FROM user_devices WHERE address = $1 LIMIT 1", [address]);
      await exec("INSERT INTO user_devices (address, device_hash, first_seen, last_seen) VALUES ($1, $2, $3, $3) ON CONFLICT DO NOTHING", [address, meta.deviceHash, now]);
      if (others) {
        await recordEvent({ address, kind: "new_device_login", severity: "warn", ipHash: meta.ipHash, details: { userAgent: meta.userAgent } });
      }
      const shared = await one("SELECT COUNT(DISTINCT address)::int AS n FROM user_devices WHERE device_hash = $1", [meta.deviceHash]);
      if ((shared?.n ?? 0) >= 4) {
        await recordEvent({ address, kind: "shared_device", severity: "warn", details: { accounts: shared?.n } });
      }
    } else {
      await exec("UPDATE user_devices SET last_seen = $3 WHERE address = $1 AND device_hash = $2", [address, meta.deviceHash, now]);
    }
  }
  await recordEvent({ address, kind: "login", severity: "info", ipHash: meta.ipHash });
  if (Math.random() < 0.02)
    await pruneExpired().catch(() => {
      return;
    });
  return { token, newDevice };
}
async function destroySession(token) {
  await exec("DELETE FROM sessions WHERE token = $1", [hashToken(token)]);
}
function bearerToken(c) {
  const h2 = c.req.header("authorization");
  if (!h2 || !h2.startsWith("Bearer "))
    return null;
  const t = h2.slice(7).trim();
  return t.length > 0 && t.length < 200 ? t : null;
}
async function userForToken(token) {
  const h2 = hashToken(token);
  const now = Date.now();
  const row = await one(`SELECT u.*, s.token AS s_token, s.created_at AS s_created, s.elevated_until AS s_elev,
            s.device_hash AS s_device, s.last_seen AS s_seen
     FROM sessions s JOIN users u ON u.address = s.address
     WHERE s.token = $1 AND s.expires_at > $2`, [h2, now]);
  if (!row)
    return null;
  if (!row.s_seen || now - Number(row.s_seen) > 5 * 60000) {
    await exec("UPDATE sessions SET last_seen = $2 WHERE token = $1", [h2, now]);
  }
  const { s_token, s_created, s_elev, s_device, s_seen: _seen, ...user } = row;
  return {
    user,
    session: {
      id: s_token.slice(0, 16),
      tokenHash: s_token,
      createdAt: Number(s_created ?? 0),
      elevatedUntil: Number(s_elev ?? 0),
      deviceHash: s_device
    }
  };
}
var requireAuth = async (c, next) => {
  const token = bearerToken(c);
  const found = token ? await userForToken(token) : null;
  if (!found)
    return c.json({ error: "Sign in required" }, 401);
  c.set("user", found.user);
  c.set("session", found.session);
  await next();
};
function str(v2, max) {
  if (typeof v2 !== "string")
    return null;
  const t = v2.trim();
  return t.length > 0 && t.length <= max ? t : null;
}
function optStr(v2, max) {
  return typeof v2 === "string" ? v2.trim().slice(0, max) : "";
}
function addr(v2) {
  return typeof v2 === "string" && isAddress(v2) ? v2.toLowerCase() : null;
}
function usdcAmount(v2) {
  if (typeof v2 !== "string" && typeof v2 !== "number")
    return null;
  const s = String(v2).trim();
  if (!/^\d{1,9}(\.\d{1,6})?$/.test(s))
    return null;
  return Number(s) > 0 ? s : null;
}
function httpsUrl(v2) {
  if (typeof v2 !== "string" || v2.length > 600)
    return null;
  try {
    const u = new URL(v2);
    return u.protocol === "https:" ? u.toString() : null;
  } catch {
    return null;
  }
}
function countryCode(v2) {
  return typeof v2 === "string" && /^[A-Za-z]{2}$/.test(v2) ? v2.toUpperCase() : null;
}
function rateLimit(name, limit, windowMs) {
  return async (c, next) => {
    const ip = (c.req.header("x-forwarded-for") ?? "local").split(",").pop().trim();
    const key = `${name}:${ip}`;
    const now = Date.now();
    const rows = await q(`INSERT INTO rate_limits (key, n, reset_at) VALUES ($1, 1, $2)
       ON CONFLICT (key) DO UPDATE SET
         n = CASE WHEN rate_limits.reset_at < $3 THEN 1 ELSE rate_limits.n + 1 END,
         reset_at = CASE WHEN rate_limits.reset_at < $3 THEN $2 ELSE rate_limits.reset_at END
       RETURNING n, reset_at`, [key, now + windowMs, now]);
    const row = rows[0];
    if (row && row.n > limit) {
      c.header("Retry-After", String(Math.max(1, Math.ceil((row.reset_at - now) / 1000))));
      return c.json({ error: "Too many requests. Please wait a moment." }, 429);
    }
    await next();
  };
}
async function upsertUser(input) {
  const rows = await q(`INSERT INTO users (address, method, circle_wallet_id, display_name, created_at)
     VALUES ($1, $2, $3, '', $4)
     ON CONFLICT (address) DO UPDATE SET circle_wallet_id = COALESCE($3, users.circle_wallet_id)
     RETURNING *`, [input.address, input.method, input.walletId ?? null, Date.now()]);
  return rows[0];
}

